import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useTheme } from '../context/ThemeContext';
import { useAuth } from '../context/AuthContext';
import { searchProducts, adminLogout } from '../services/api';
import { isAdmin, getAdminUser, clearAuthData } from '../util/auth';
import AdminNotifications from './AdminNotifications';

// Direct function definition to avoid import issues
const isAdminAuthenticated = () => {
  const adminToken = localStorage.getItem('adminToken');
  return !!adminToken;
};

const ModernNavbar = ({ cartCount, user, onLogout }) => {
  const navigate = useNavigate();
  const { isDarkMode, toggleTheme } = useTheme();
  const { user: authUser } = useAuth();
  const currentUser = authUser || user;
  const [showLogoutModal, setShowLogoutModal] = useState(false);
  
  // Check if current page is admin page
  const isAdminPage = window.location.pathname.startsWith('/admin');
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [showSearch, setShowSearch] = useState(false);
  const [adminAuthState, setAdminAuthState] = useState(isAdminAuthenticated());
  const [isScrolled, setIsScrolled] = useState(false);
  const [placeholderIndex, setPlaceholderIndex] = useState(0);

  // Get gradient colors for fallback background
  const getCategoryGradient = (category) => {
    const gradients = {
      milk: 'from-blue-200 to-blue-400 dark:from-blue-800 dark:to-blue-600',
      ghee: 'from-amber-200 to-amber-400 dark:from-amber-800 dark:to-amber-600',
      cheese: 'from-yellow-200 to-yellow-400 dark:from-yellow-800 dark:to-yellow-600',
      butter: 'from-orange-200 to-orange-400 dark:from-orange-800 dark:to-orange-600',
      curd: 'from-green-200 to-green-400 dark:from-green-800 dark:to-green-600',
      paneer: 'from-purple-200 to-purple-400 dark:from-purple-800 dark:to-purple-600',
      cream: 'from-pink-200 to-pink-400 dark:from-pink-800 dark:to-pink-600',
      yogurt: 'from-teal-200 to-teal-400 dark:from-teal-800 dark:to-teal-600',
      lassi: 'from-cyan-200 to-cyan-400 dark:from-cyan-800 dark:to-cyan-600',
      buttermilk: 'from-lime-200 to-lime-400 dark:from-lime-800 dark:to-lime-600',
      sweets: 'from-rose-200 to-pink-300 dark:from-rose-800 dark:to-pink-600',
      cake: 'from-fuchsia-200 to-pink-400 dark:from-fuchsia-800 dark:to-pink-600'
    };
    return gradients[category] || 'from-gray-200 to-gray-400 dark:from-gray-700 dark:to-gray-500';
  };

  // Get emoji for each category
  const getCategoryEmoji = (category) => {
    const emojis = {
      milk: '🥛',
      ghee: '🍯',
      cheese: '🧀',
      butter: '🧈',
      curd: '🥣',
      paneer: '🧊',
      cream: '🍦',
      yogurt: '🍶',
      lassi: '🥤',
      buttermilk: '🫙',
      sweets: '🍬',
      cake: '🍰'
    };
    return emojis[category] || '🥛';
  };

  // Derive category from product name if not available
  const deriveCategoryFromName = (name) => {
    const lowerName = name?.toLowerCase() || '';
    if (lowerName.includes('milk')) return 'milk';
    if (lowerName.includes('ghee')) return 'ghee';
    if (lowerName.includes('cheese')) return 'cheese';
    if (lowerName.includes('butter')) return 'butter';
    if (lowerName.includes('curd')) return 'curd';
    if (lowerName.includes('paneer')) return 'paneer';
    if (lowerName.includes('cream') || lowerName.includes('creme') || lowerName.includes('fraiche')) return 'cream';
    if (lowerName.includes('yogurt')) return 'yogurt';
    if (lowerName.includes('lassi')) return 'lassi';
    if (lowerName.includes('buttermilk')) return 'buttermilk';
    return 'milk';
  };
  
  // Animated placeholder texts
  const placeholderTexts = [
    "",
    "🥛 ",
    "🍯🥛 ",
    "🍦🍯🥛 ",
    "🥤🍦🍯🥛 ",
    "🥣🥤🍦🍯🥛 ",
    "🧀🥤🍦🍯🧊🥛",
    "🧀🥤🍦🍯🧊🥛🧈",
    "🧀🥤🍦🍯🧊🥛🧈🫙",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛🧈",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛🧈🫙",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛🧈🫙🍶",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛🧈🫙",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛🧈",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊🥛",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯🧊",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦🍯",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤🍦",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀🥤",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶🧀",
    "🧀🥤🍦🍯🧊🥛🧈🫙🍶",
    "🧀🥤🍦🍯🧊🥛🧈🫙",
    "🧀🥤🍦🍯🧊🥛🧈",
    "🧀🥤🍦🍯🧊🥛",
    "🧀🥤🍦🍯🧊",
    "🥤🍦🍯🥛 ",
    "🍦🍯🥛 ",
    "🍯🥛 ",
    "🥛 ",
    ""
  ];

  // Handle scroll effect
  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Placeholder animation effect
  useEffect(() => {
    const interval = setInterval(() => {
      setPlaceholderIndex((prev) => (prev + 1) % placeholderTexts.length);
    }, 2000);
    
    // Add CSS to hide scrollbar
    const style = document.createElement('style');
    style.textContent = `
      .hide-scrollbar::-webkit-scrollbar {
        display: none;
      }
      .hide-scrollbar {
        -ms-overflow-style: none;
        scrollbar-width: none;
      }
    `;
    document.head.appendChild(style);
    
    return () => {
      clearInterval(interval);
      document.head.removeChild(style);
    };
  }, [placeholderTexts.length]);

  // Handle notification click
  const handleNotificationClick = (orderId) => {
    if (orderId === 'all') {
      navigate('/admin');
      setTimeout(() => {
        window.location.hash = '#payments';
      }, 100);
    } else {
      navigate('/admin');
      setTimeout(() => {
        sessionStorage.setItem('targetPayment', orderId);
        window.location.hash = '#payments';
      }, 100);
    }
  };

  useEffect(() => {
    const handleStorageChange = () => {
      setAdminAuthState(isAdminAuthenticated());
    };
    
    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('adminAuthChange', handleStorageChange);
    const interval = setInterval(handleStorageChange, 500);
    
    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('adminAuthChange', handleStorageChange);
      clearInterval(interval);
    };
  }, []);

  const handleSearch = async (e) => {
    const query = e.target.value;
    setSearchQuery(query);
    setShowSearch(true); // Keep popup open when typing

    if (query.length > 0) {
      try {
        // Get more precise results with smaller limit
        const results = await searchProducts(query, 5);
        
        // If no results, try with all products as fallback
        if (results.data && results.data.length === 0) {
          const allProducts = await searchProducts('', 10);
          setSearchResults(allProducts.data);
        } else {
          setSearchResults(results.data);
        }
      } catch (error) {
        console.error('Search error:', error);
        setSearchResults([]);
      }
    } else {
      // Clear results but keep popup open
      setSearchResults([]);
    }
  };

  const handleAdminLogout = async () => {
    try {
      await adminLogout();
      clearAuthData();
      setAdminAuthState(false);
      navigate('/admin/login');
    } catch (error) {
      console.error('Admin logout error:', error);
    }
  };

  return (
    <>
      {/* Modern Glass Effect Navbar */}
      <nav className={`fixed top-0 left-0 right-0 z-[60] transition-all duration-300 ${
        isScrolled 
          ? 'bg-white/80 dark:bg-gray-900/80 backdrop-blur-xl border-b border-white/20 dark:border-gray-800/20 shadow-lg' 
          : 'bg-white/90 dark:bg-gray-900/90 backdrop-blur-lg border-b border-white/10 dark:border-gray-800/10'
      }`}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            
            {/* Logo */}
            <Link to="/" className="flex items-center space-x-3 group">
              <div className="relative">
                <div className="w-10 h-10 relative">
                  <div className="absolute inset-0 bg-gradient-to-br from-blue-400 to-purple-600 rounded-lg opacity-25 blur-lg group-hover:opacity-35 transition-opacity duration-300"></div>
                  <div className="absolute inset-0 rounded-lg overflow-hidden shadow-lg transform transition-transform duration-300 group-hover:rotate-6 group-hover:scale-105">
                    <img
                      src="/icon.svg"
                      alt="Pinqoza"
                      className="w-full h-full"
                      draggable="false"
                    />
                  </div>
                </div>
              </div>
              <div className="flex flex-col">
                <span className="text-xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent">
                  Pinqoza
                </span>
                <span className="text-xs text-gray-500 dark:text-gray-400">Shop Everything</span>
              </div>
            </Link>

            {/* Search Bar */}
            <div className="hidden md:block flex-1 max-w-lg mx-8">
              <div className="relative">
                <div 
                  className="w-full px-5 py-3 pl-12 bg-gradient-to-r from-gray-50 to-gray-100 dark:from-black dark:to-black border border-gray-300 dark:border-gray-600 rounded-full focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all duration-200 text-base cursor-pointer hover:shadow-lg hover:scale-[1.02] transform"
                  onClick={() => setShowSearch(!showSearch)}
                >
                  <input
                    type="text"
                    placeholder={placeholderTexts[placeholderIndex]}
                    value={searchQuery}
                    onChange={handleSearch}
                    onFocus={() => setShowSearch(true)}
                    className="w-full bg-transparent border-none outline-none text-gray-700 dark:text-gray-300 placeholder-gray-500 dark:placeholder-gray-400 pr-10"
                  />
                  
                  {/* Clear Search Button - Modern Cross Icon */}
                  {searchQuery && (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        setSearchQuery('');
                        setSearchResults([]);
                      }}
                      className="absolute right-3 top-1/2 transform -translate-y-1/2 w-6 h-6 rounded-full bg-gray-200 dark:bg-gray-600 hover:bg-gray-300 dark:hover:bg-gray-500 flex items-center justify-center transition-all duration-200 hover:scale-110 group"
                    >
                      <svg 
                        className="w-3.5 h-3.5 text-gray-500 dark:text-gray-400 group-hover:text-gray-700 dark:group-hover:text-gray-200 transition-colors" 
                        fill="none" 
                        stroke="currentColor" 
                        viewBox="0 0 24 24"
                      >
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                      </svg>
                    </button>
