                {/* Search Results Dropdown - Modern Design */}
                {showSearch && (
                  <div className="absolute top-full mt-3 w-[140%] left-[-20%] bg-white/90 dark:bg-black/90 backdrop-blur-md rounded-2xl shadow-[0_20px_60px_-15px_rgba(0,0,0,0.4)] border border-gray-300/50 dark:border-gray-600/50 max-h-[450px] overflow-y-auto transform transition-all duration-500 ease-out animate-in slide-in-from-top-3 fade-in-0 z-50 hide-scrollbar" style={{ WebkitBackdropFilter: 'blur(8px)', backdropFilter: 'blur(8px)' }}>
