                                        e.target.style.display = 'none';
                                        e.target.nextSibling.style.display = 'flex';
                                      }}
                                    />
                                  ) : null}
                                  
                                  {/* Fallback Image based on category */}
                                  <div 
                                    className={`w-full h-full flex items-center justify-center bg-gradient-to-br ${getCategoryGradient(product.category || deriveCategoryFromName(product.name))} ${product.image ? 'hidden' : 'flex'}`}
