                                  {product.name}
                                </h4>
                                <div className="flex items-center space-x-5 mt-3">
                                  <span className="text-base px-4 py-2 bg-gradient-to-r from-gray-100 to-gray-200 dark:from-gray-700 dark:to-gray-600 text-gray-700 dark:text-gray-300 rounded-full font-semibold shadow-sm">
