                                    </svg>
                                    <span className="text-base font-semibold text-gray-600 dark:text-gray-400">4.8</span>
                                  </div>
                                  <div className="flex items-center space-x-2">
                                    <svg className="w-4 h-4 text-green-500" fill="currentColor" viewBox="0 0 24 24">
                                      <path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/>
                                    </svg>
                                    <span className="text-sm font-medium text-green-600 dark:text-green-400">In Stock</span>
                                  </div>
                                </div>
                              </div>
                              
                              {/* Price and Action */}
                              <div className="flex items-center space-x-5 flex-shrink-0">
                                <div className="text-right">
                                  <p className="text-2xl font-black text-transparent bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text">₹{product.price}</p>
                                  <p className="text-sm text-gray-500 dark:text-gray-400 line-through">₹{Math.round(product.price * 1.25)}</p>
                                </div>
                                <div className="opacity-0 group-hover:opacity-100 transition-all duration-300 transform translate-x-3 group-hover:translate-x-0">
                                  <div className="bg-gradient-to-br from-blue-500 to-purple-600 text-white rounded-2xl p-3 shadow-xl transform transition-all duration-300 group-hover:scale-110 group-hover:rotate-12">
